		return false;
	}

	@ConfigItem(
		keyName = "showAvatarDamage",
		name = "Your avatar damage",
		description = "Show the damage you have dealt to the enemy<br>"
			+ "Avatar this game.",
		position = 3,
		section = MATCH
	)
