	@ConfigItem(
		keyName = "showLobbyInfo",
		name = "Lobby info",
		description = "In the Soul Wars lobby, show how many<br>"
			+ "players are waiting and the time until the<br>"
			+ "next game starts.",
		position = 9,
		section = MATCH
	)
	default boolean showLobbyInfo()
	{
		return true;
	}

	// ----- Session record -----

	@ConfigItem(
		keyName = "showSessionRecord",
		name = "Session win/loss",
		description = "Show your win/loss record for the games you<br>"
			+ "have finished this session, e.g. 3W / 1L.",
		position = 0,
		section = SESSION
	)
