	}

	@ConfigItem(
		keyName = "showTeamComposition",
		name = "Team composition this session",
		description = "Show this session's record split by team and<br>"
			+ "result: red wins / red losses / blue wins /<br>"
			+ "blue losses (RW / RL / BW / BL).",
		position = 1,
		section = SESSION
	)
