			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
				return true;
			default:
				return false;
		}
	}

	/**
	 * Clicks that issue a new action or movement, which the game answers by cancelling any
	 * current follow. Interface clicks (prayers, spells on yourself, config) don't cancel a
	 * follow, so they are deliberately not listed; the interaction check in updateFollow is
	 * the backstop for anything missed here.
	 */
	private static boolean cancelsFollow(MenuAction action)
	{
		switch (action)
		{
			case WALK:
			case PLAYER_FIRST_OPTION:
			case PLAYER_SECOND_OPTION:
			case PLAYER_THIRD_OPTION:
			case PLAYER_FOURTH_OPTION:
			case PLAYER_FIFTH_OPTION:
			case PLAYER_SIXTH_OPTION:
			case PLAYER_SEVENTH_OPTION:
			case PLAYER_EIGHTH_OPTION:
			case NPC_FIRST_OPTION:
			case NPC_SECOND_OPTION:
			case NPC_THIRD_OPTION:
			case NPC_FOURTH_OPTION:
			case NPC_FIFTH_OPTION:
			case GAME_OBJECT_FIRST_OPTION:
			case GAME_OBJECT_SECOND_OPTION:
			case GAME_OBJECT_THIRD_OPTION:
			case GAME_OBJECT_FOURTH_OPTION:
			case GAME_OBJECT_FIFTH_OPTION:
			case GROUND_ITEM_FIRST_OPTION:
			case GROUND_ITEM_SECOND_OPTION:
			case GROUND_ITEM_THIRD_OPTION:
			case GROUND_ITEM_FOURTH_OPTION:
			case GROUND_ITEM_FIFTH_OPTION:
			case ITEM_USE_ON_PLAYER:
			case ITEM_USE_ON_NPC:
			case ITEM_USE_ON_GAME_OBJECT:
			case ITEM_USE_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_PLAYER:
			case WIDGET_TARGET_ON_NPC:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GROUND_ITEM:
				return true;
			default:
				return false;
		}
	}

	// ----- overlay accessor (client thread only) -----

	List<StatusLine> getStatusModel()
	{
		return statusModel;
	}
}

package com.anonyser.followplus;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GraphicsEnvironment;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JFrame;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;

/**
 * The external always-on-top window (AFK Overlay style): stays visible while the RuneLite client
 * is buried behind other windows, which is the whole point for people running alts. Undecorated,
 * drag anywhere to move, position saved to config. It renders the {@link StatusLine} model the
 * plugin builds; a label per line, updated in place so the text never jitters, re-packing only
 * when the number of lines changes. This class never touches the client API.
 */
class FollowPlusWindow extends JFrame
{
	private static final Color BG = new Color(24, 24, 24);
	private static final Color BORDER = new Color(70, 70, 70);
	private static final Color FG = new Color(220, 220, 220);
	private static final Color MUTED = new Color(160, 160, 160);
	private static final int WIDTH_PX = 220;

	private static final String KEY_X = "windowX";
	private static final String KEY_Y = "windowY";
	// Movement under this many pixels between press and release counts as a click, not a drag.
	private static final int CLICK_SLOP_PX = 4;

	private final ConfigManager configManager;
	private final Runnable onClick;
	private final JPanel content;
	private final Font normalFont;
	private final Font boldFont;
	private final List<JLabel> labels = new ArrayList<>();
	private final Timer flashTimer = new Timer(300, e -> applyFlash());
	private List<StatusLine> model;

	private Point dragPoint;
	private Point pressScreen;

	FollowPlusWindow(ConfigManager configManager, Runnable onClick)
	{
		this.configManager = configManager;
		this.onClick = onClick;

		setTitle("Soul Wars Status");
		setUndecorated(true);
		setAlwaysOnTop(true);
		setType(Type.NORMAL);
		// never steal focus from the game (or whatever the main account is doing)
		setFocusableWindowState(false);
		setDefaultCloseOperation(DISPOSE_ON_CLOSE);

		content = new JPanel()
		{
			@Override
			public Dimension getPreferredSize()
			{
				// fixed width so text changes don't make the window wobble
				return new Dimension(WIDTH_PX, super.getPreferredSize().height);
			}
		};
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(BG);
		content.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(BORDER),
			BorderFactory.createEmptyBorder(6, 10, 8, 10)));

		normalFont = FontManager.getRunescapeFont();
		boldFont = normalFont.deriveFont(Font.BOLD);

		final JLabel title = makeLabel("Soul Wars Status", MUTED);
		content.add(title);
		setContentPane(content);

		// drag anywhere to move; a click (no real drag) raises the RuneLite client. The labels have
		// no listeners so events fall through to us.
		final MouseAdapter dragger = new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				dragPoint = e.getPoint();
				pressScreen = e.getLocationOnScreen();
			}

			@Override
			public void mouseDragged(MouseEvent e)
			{
				if (dragPoint != null)
				{
					final Point p = getLocation();
					setLocation(p.x + e.getX() - dragPoint.x, p.y + e.getY() - dragPoint.y);
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				final boolean click = pressScreen != null
					&& e.getLocationOnScreen().distance(pressScreen) <= CLICK_SLOP_PX;
				dragPoint = null;
				pressScreen = null;
				if (click)
				{
					if (onClick != null)
					{
						onClick.run();
					}
				}
				else
				{
					savePosition();
				}
			}
		};
		addMouseListener(dragger);
		addMouseMotionListener(dragger);

		pack();
		loadPosition();
		flashTimer.start();
	}

	@Override
	public void dispose()
	{
		flashTimer.stop();
		super.dispose();
	}

	/** EDT only. */
	void update(List<StatusLine> model)
	{
		this.model = model;
		boolean structureChanged = false;
		if (labels.size() != model.size())
		{
			rebuild(model.size());
			structureChanged = true;
		}
		for (int i = 0; i < model.size(); i++)
		{
			applyLine(labels.get(i), model.get(i));
		}
		if (structureChanged)
		{
			pack();
		}
	}

	/** Re-tints flashing lines each timer tick so they pulse between updates. */
	private void applyFlash()
	{
		final List<StatusLine> m = model;
		if (m == null)
		{
			return;
		}
		final Color c = StatusLine.flashColor(System.currentTimeMillis());
		for (int i = 0; i < m.size() && i < labels.size(); i++)
		{
			if (m.get(i).flash)
			{
				labels.get(i).setForeground(c);
			}
		}
	}

	private void rebuild(int count)
	{
		for (JLabel label : labels)
		{
			content.remove(label);
		}
		labels.clear();
		for (int i = 0; i < count; i++)
		{
			final JLabel label = makeLabel("", FG);
			content.add(label);
			labels.add(label);
		}
		content.revalidate();
	}

	private void applyLine(JLabel label, StatusLine line)
	{
		label.setText(line.right != null ? line.left + ":  " + line.right : line.left);
		label.setForeground(line.flash
			? StatusLine.flashColor(System.currentTimeMillis())
			: (line.color != null ? line.color : FG));
		label.setFont(line.header ? boldFont : normalFont);
	}

	private static JLabel makeLabel(String text, Color color)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(FontManager.getRunescapeFont());
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
		return label;
	}

	private void loadPosition()
	{
		final Integer x = configManager.getConfiguration(FollowPlusConfig.GROUP, KEY_X, Integer.class);
		final Integer y = configManager.getConfiguration(FollowPlusConfig.GROUP, KEY_Y, Integer.class);
		final Rectangle screen = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
		if (x != null && y != null && screen.intersects(new Rectangle(x, y, WIDTH_PX, 60)))
		{
			setLocation(x, y);
		}
		else
		{
			setLocation(100, 100);
		}
	}

	private void savePosition()
	{
		configManager.setConfiguration(FollowPlusConfig.GROUP, KEY_X, getX());
		configManager.setConfiguration(FollowPlusConfig.GROUP, KEY_Y, getY());
	}
}

package com.anonyser.followplus;

import java.util.HashMap;
import java.util.Map;

/**
 * Locks onto the one Soul Wars widget whose mm:ss text actually counts down like a clock.
 * The exact child holding the match timer isn't verified anywhere, so every time-looking text
 * in the game interface is fed in as a candidate and nothing is displayed until one of them
 * has behaved like a countdown for a few seconds - a wrong timer is worse than "Unknown".
 */
class GameTimerTracker
{
	/** A candidate must tick down consistently for this long before it is trusted. */
	private static final long LOCK_AFTER_MS = 3000;
	/** Allowed disagreement between elapsed wall time and the displayed drop, in seconds. */
	private static final int TOLERANCE_SECONDS = 2;
	/** Forget observations this old (widget vanished, match ended). */
	private static final long STALE_MS = 3000;

	private static final class Candidate
	{
		int anchorSeconds;
		long anchorMs;
		int lastSeconds;
		long lastMs;
	}

	private final Map<Integer, Candidate> candidates = new HashMap<>();
	private int lockedKey = -1;

	void reset()
	{
		candidates.clear();
		lockedKey = -1;
	}

	/** Feed every parsed time text: a stable key for the widget, its value, and the wall clock. */
	void observe(int key, int seconds, long nowMs)
	{
		Candidate c = candidates.get(key);
		if (c == null)
		{
			c = new Candidate();
			c.anchorSeconds = seconds;
			c.anchorMs = nowMs;
			candidates.put(key, c);
		}
		else if (seconds > c.lastSeconds || nowMs - c.lastMs > STALE_MS)
		{
			// went up or vanished for a while - restart the countdown check from here
			c.anchorSeconds = seconds;
			c.anchorMs = nowMs;
			if (lockedKey == key)
			{
				lockedKey = -1;
			}
		}
		else
		{
			final long elapsed = nowMs - c.anchorMs;
			final long drop = c.anchorSeconds - seconds;
			if (Math.abs(drop - elapsed / 1000.0) > TOLERANCE_SECONDS)
			{
				// not moving like a clock (a static score, a kill count, ...)
				c.anchorSeconds = seconds;
				c.anchorMs = nowMs;
				if (lockedKey == key)
				{
					lockedKey = -1;
				}
			}
			else if (elapsed >= LOCK_AFTER_MS && lockedKey == -1)
			{
				lockedKey = key;
			}
		}
		c.lastSeconds = seconds;
		c.lastMs = nowMs;
	}

	/** Seconds left on the locked countdown, or -1 while no widget has proven itself. */
	int getSeconds(long nowMs)
	{
		final Candidate c = lockedKey >= 0 ? candidates.get(lockedKey) : null;
		if (c == null || nowMs - c.lastMs > STALE_MS)
		{
			return -1;
		}
		return c.lastSeconds;
	}

	boolean isLocked()
	{
		return lockedKey >= 0;
	}

	int lockedKey()
	{
		return lockedKey;
	}
}

package com.anonyser.followplus;

final class PrayerDrainCalculator
{
	private PrayerDrainCalculator()
	{
	}

	/**
	 * Seconds until prayer points reach zero, using the exact math of RuneLite's core prayer
	 * plugin (PrayerPlugin#getEstimatedTimeRemaining), which follows
	 * https://oldschool.runescape.wiki/w/Prayer#Prayer_drain_mechanics:
	 * drain resistance = 2 * prayer bonus + 60; each point lasts
	 * 0.6s * drainResistance / drainEffect.
	 *
	 * @param prayerPoints current prayer points (boosted level)
	 * @param drainEffect  sum of the drain effects of all active prayers
	 * @param prayerBonus  total prayer bonus from worn equipment
	 * @return seconds remaining, or -1 when no prayer is draining
	 */
	static double secondsRemaining(int prayerPoints, int drainEffect, int prayerBonus)
	{
		if (drainEffect <= 0)
		{
			return -1;
		}
		if (prayerPoints <= 0)
		{
			return 0;
		}
		final int drainResistance = 2 * prayerBonus + 60;
		final double secondsPerPoint = 0.6 * ((double) drainResistance / drainEffect);
		return prayerPoints * secondsPerPoint;
	}
}

package com.anonyser.followplus;

/**
 * Session tally of finished Soul Wars games, split by the team you played on. Each game is recorded
 * as a win, loss or draw for Blue or Red; the counts are per-session (cleared when the session
 * starts) and drive the "Session win/loss" and "Team composition" display lines. Holds no game
 * references so it is unit-tested in isolation: the plugin decides the outcome from the final
 * avatar-kill counts and hands it in via {@link #record}. Draws are kept so a drawn game is never
 * miscounted as a loss, but the win/loss line only shows wins and losses.
 */
class SessionResultTracker
{
	enum Outcome
	{
		WIN,
		LOSS,
		DRAW
	}

	private int blueWins;
	private int blueLosses;
	private int blueDraws;
	private int redWins;
	private int redLosses;
	private int redDraws;

	void reset()
	{
		blueWins = 0;
		blueLosses = 0;
		blueDraws = 0;
		redWins = 0;
		redLosses = 0;
		redDraws = 0;
	}

	/**
	 * Records one finished game for the given team. A null outcome or an unknown team
	 * ({@link SoulWarsTeam#NONE}) is ignored so a bad read never corrupts the tally.
	 */
	void record(SoulWarsTeam team, Outcome outcome)
	{
		if (outcome == null)
		{
			return;
		}
		if (team == SoulWarsTeam.BLUE)
		{
			if (outcome == Outcome.WIN)
			{
				blueWins++;
			}
			else if (outcome == Outcome.LOSS)
			{
				blueLosses++;
			}
			else
			{
				blueDraws++;
			}
		}
		else if (team == SoulWarsTeam.RED)
		{
			if (outcome == Outcome.WIN)
			{
				redWins++;
			}
			else if (outcome == Outcome.LOSS)
			{
				redLosses++;
			}
			else
			{
				redDraws++;
			}
		}
	}

	/**
	 * Decides the outcome for {@code team} from each team's final avatar-kill count (the HUD "x/5"
	 * values): more kills than the enemy is a win, fewer is a loss, equal is a draw. Returns null
	 * when the inputs cannot decide a result (kills not read yet, or unknown team).
	 */
	static Outcome decide(int blueKills, int redKills, SoulWarsTeam team)
	{
		if (blueKills < 0 || redKills < 0
			|| (team != SoulWarsTeam.BLUE && team != SoulWarsTeam.RED))
		{
			return null;
		}
		final int mine = team == SoulWarsTeam.BLUE ? blueKills : redKills;
		final int theirs = team == SoulWarsTeam.BLUE ? redKills : blueKills;
		if (mine > theirs)
		{
			return Outcome.WIN;
		}
		if (mine < theirs)
		{
			return Outcome.LOSS;
		}
		return Outcome.DRAW;
	}

	int wins()
	{
		return blueWins + redWins;
	}

	int losses()
	{
		return blueLosses + redLosses;
	}

	int draws()
	{
		return blueDraws + redDraws;
	}

	int blueWins()
	{
		return blueWins;
	}

	int blueLosses()
	{
		return blueLosses;
	}

	int redWins()
	{
		return redWins;
	}

	int redLosses()
	{
		return redLosses;
	}
}

package com.anonyser.followplus;

/**
 * The Soul Wars in-game HUD (interface {@code SOUL_WARS_GAME} = 375). Its top-level children hold
 * the live match stats as plain text, verified live, in Blue-left / Red-right column order:
 *
 * <pre>
 *   child 11 = Blue avatar kills "x/5"     child 12 = Red avatar kills
 *   child 15 = Blue avatar health "100%"   child 16 = Red avatar health
 *   child 19 = Blue avatar strength "100%" child 20 = Red avatar strength
 *   child 23 = Time left "mm:ss"
 * </pre>
 *
 * <p>The plugin reads the widget text on the client thread; the parsing lives here so it can be
 * unit-tested. A parse miss returns -1 ("unknown") so a blank/absent widget never shows a wrong
 * number.
 */
final class SoulWarsHud
{
	static final int BLUE_KILLS = 11;
	static final int RED_KILLS = 12;
	static final int BLUE_HEALTH = 15;
	static final int RED_HEALTH = 16;
	static final int BLUE_STRENGTH = 19;
	static final int RED_STRENGTH = 20;
	static final int TIME_LEFT = 23;

	private SoulWarsHud()
	{
	}

	/** Numerator of an "x/y" fraction (e.g. avatar kills "3/5" -> 3), or -1. */
	static int parseFraction(String text)
	{
		if (text == null)
		{
			return -1;
		}
		final int slash = text.indexOf('/');
		if (slash <= 0)
		{
			return -1;
		}
		return parseIntOrNeg(text.substring(0, slash).trim());
	}

	/** A percentage (e.g. avatar strength "45%" -> 45), or -1. */
	static int parsePercent(String text)
	{
		if (text == null)
		{
			return -1;
		}
		final int pct = text.indexOf('%');
		if (pct <= 0)
		{
			return -1;
		}
		return parseIntOrNeg(text.substring(0, pct).trim());
	}

	private static int parseIntOrNeg(String s)
	{
		try
		{
			final int v = Integer.parseInt(s);
			return v < 0 ? -1 : v;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}
}

package com.anonyser.followplus;

import java.util.List;
import java.util.regex.Pattern;

/**
 * Reads the Soul Wars lobby board (interface 434). Verified from live captures: the board holds
 * its labels and values in separate, consecutive widgets - "Players Waiting" then the count,
 * "Next Game Start" then a duration. The count and the timer both change format with lobby state:
 * below the minimum the game shows "5/20" and "-", and once enough players are in it switches to a
 * bare count ("28") and a real countdown ("3 minutes", "30 seconds"). Rather than parse any of
 * that, the value widget after each label is shown verbatim, so every format the game uses is
 * mirrored exactly. A value is ignored only if it is itself one of the labels (a missing widget).
 */
final class SoulWarsLobbyReader
{
	private static final Pattern TAG = Pattern.compile("<[^>]*>");

	private SoulWarsLobbyReader()
	{
	}

	static final class Result
	{
		final String playersWaiting; // null = unknown, e.g. "5/20" or "28"
		final String nextGame;       // null = unknown, e.g. "3 minutes", "30 seconds", "-"

		Result(String playersWaiting, String nextGame)
		{
			this.playersWaiting = playersWaiting;
			this.nextGame = nextGame;
		}
	}

	static Result read(List<String> orderedTexts)
	{
		String players = null;
		String nextGame = null;
		for (int i = 0; i + 1 < orderedTexts.size(); i++)
		{
			final String label = clean(orderedTexts.get(i)).toLowerCase();
			final String value = clean(orderedTexts.get(i + 1));
			if (isLabel(value))
			{
				continue;
			}
			if (players == null && label.contains("players waiting"))
			{
				players = value.isEmpty() ? null : value;
			}
			else if (nextGame == null && label.contains("next game"))
			{
				nextGame = value.isEmpty() ? null : value;
			}
		}
		return new Result(players, nextGame);
	}

	private static boolean isLabel(String value)
	{
		final String low = value.toLowerCase();
		return low.contains("players waiting") || low.contains("next game");
	}

	private static String clean(String s)
	{
		return s == null ? "" : TAG.matcher(s).replaceAll("").trim();
	}
}

package com.anonyser.followplus;

import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * Per-game personal contribution counters that the game only shows on its end screen, so they're
 * tallied client-side (the same display-only approach the existing "Soul Wars" hub plugin uses):
 * <ul>
 *   <li><b>captures</b> — a capture chat line naming your team and an area, while you stand in it,</li>
 *   <li><b>fragments sacrificed</b> — the drop in your inventory fragment count during a game
 *       (Soul Wars is a safe minigame, so fragments only leave your pack by charging the obelisk;
 *       this avoids depending on the order the game fires the inventory update vs the chat line),</li>
 *   <li><b>bones buried</b> — the "bury the bones" line,</li>
 *   <li><b>avatar damage</b> — your hitsplats on the enemy Avatar, fed in from the plugin.</li>
 * </ul>
 * Counters reset each game; the inventory fragment count persists (it's account state, not a score).
 * The three capture areas are the verified Soul Wars world areas.
 */
class SoulWarsMatchTracker
{
	static final WorldArea WEST_GRAVEYARD = new WorldArea(2157, 2893, 11, 11, 0);
	static final WorldArea OBELISK = new WorldArea(2199, 2904, 16, 16, 0);
	static final WorldArea EAST_GRAVEYARD = new WorldArea(2248, 2920, 11, 11, 0);
	// The capture line fires when you may be a few tiles off the exact area, so count a capture when
	// you are within this many tiles of it rather than dead-on the box.
	static final int CAPTURE_TOLERANCE = 12;

	private int captures;
	private int fragmentsSacrificed;
	private int bonesBuried;
	private int avatarDamage;
	private int inventoryFragments;

	/** Clears the per-game counters (called when a game starts). Inventory count is left alone. */
	void reset()
	{
		captures = 0;
		fragmentsSacrificed = 0;
		bonesBuried = 0;
		avatarDamage = 0;
	}

	void addAvatarDamage(int amount)
	{
		if (amount > 0)
		{
			avatarDamage += amount;
		}
	}

	/**
	 * Feeds the current soul-fragment count in the inventory. A drop in the count during a game is
	 * counted as fragments sacrificed; the latest count is always remembered so the baseline is
	 * right when you next sacrifice.
	 */
	void onInventoryFragments(int count, boolean inGame)
	{
		final int c = Math.max(0, count);
		if (inGame && c < inventoryFragments)
		{
			fragmentsSacrificed += inventoryFragments - c;
		}
		inventoryFragments = c;
	}

	/**
	 * Applies a game chat line. The bones line is matched first. A capture only counts when the line
	 * names your team and an area you are currently standing in.
	 */
	void onChatMessage(String message, SoulWarsTeam team, WorldPoint location)
	{
		if (message == null || team == null || team == SoulWarsTeam.NONE)
		{
			return;
		}
		final String m = message.toLowerCase();
		if (m.contains("you bury the bones"))
		{
			bonesBuried++;
			return;
		}
		if (!m.contains(team.chatIdentifier()))
		{
			return;
		}
		final WorldArea area = capturedArea(m);
		if (area != null && location != null && area.distanceTo(location) <= CAPTURE_TOLERANCE)
		{
			captures++;
		}
	}

	/** The area a capture line refers to, or null if the line isn't a capture. */
	static WorldArea capturedArea(String lowerMessage)
	{
		if (lowerMessage.contains("western graveyard"))
		{
			return WEST_GRAVEYARD;
		}
		if (lowerMessage.contains("eastern graveyard"))
		{
			return EAST_GRAVEYARD;
		}
		if (lowerMessage.contains("soul obelisk"))
		{
			return OBELISK;
		}
		return null;
	}

	int captures()
	{
		return captures;
	}

	int fragmentsSacrificed()
	{
		return fragmentsSacrificed;
	}

	int bonesBuried()
	{
		return bonesBuried;
	}

	int avatarDamage()
	{
		return avatarDamage;
	}
}

package com.anonyser.followplus;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingConstants;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.api.Experience;
import net.runelite.api.Skill;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * Side panel: Zeal balance and lifetime score, crates that buys, the daily Zeal-XP tally with a
 * reset countdown, a Zeal calculator (From and Target both editable and auto-filled from your own
 * levels, each independently entered as a level or as XP with flexible number entry) and a
 * quick-reference of XP per Zeal Token. Pure Swing; the plugin feeds it primitives on the EDT.
 */
class SoulWarsPanel extends PluginPanel
{
	static final Skill[] SKILLS = {
		Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS,
		Skill.RANGED, Skill.MAGIC, Skill.PRAYER
	};
	private static final long MS_PER_DAY = 86_400_000L;

	private final JLabel tokensValue = value();
	private final JLabel lifetimeValue = value();
	private final JLabel cratesValue = value();
	private final JLabel dailyValue = value();
	private final JLabel resetsValue = value();

	private final JComboBox<String> fromModeBox = new JComboBox<>(new String[]{"Level", "XP"});
	private final JComboBox<String> targetModeBox = new JComboBox<>(new String[]{"Level", "XP"});
	private final JTextField[] from = new JTextField[SKILLS.length];
	private final JTextField[] target = new JTextField[SKILLS.length];
	private final JLabel[] zealNeeded = new JLabel[SKILLS.length];
	private final int[] currentXp = new int[SKILLS.length];
	private final int[] currentLvl = new int[SKILLS.length];
	private boolean seeded;
	private boolean fromXpMode;
	private boolean targetXpMode;

	SoulWarsPanel()
	{
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		final JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);

		body.add(title("Zeal"));
		body.add(buildSummary());

		body.add(gap());
		body.add(title("Zeal calculator"));
		body.add(buildCalculator());

		body.add(gap());
		body.add(blurb());
		body.add(title("XP per Zeal Token"));
		body.add(buildReference());

		add(body, BorderLayout.NORTH);
	}

	private JPanel buildSummary()
	{
		final JPanel grid = new JPanel(new GridLayout(0, 2, 6, 3));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.add(muted("Zeal tokens"));
		grid.add(tokensValue);
		grid.add(muted("Lifetime"));
		grid.add(lifetimeValue);
		grid.add(muted("Crates"));
		grid.add(cratesValue);
		grid.add(muted("XP today"));
		grid.add(dailyValue);
		grid.add(muted("Resets in"));
		grid.add(resetsValue);
		return grid;
	}

	private JPanel buildCalculator()
	{
		final JPanel grid = new JPanel(new GridLayout(SKILLS.length + 1, 4, 5, 4));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		// header row: the two column dropdowns pick how From / Target are entered (level vs XP)
		grid.add(header("Skill"));
		fromModeBox.addActionListener(e -> onFromModeChanged());
		grid.add(fromModeBox);
		targetModeBox.addActionListener(e -> onTargetModeChanged());
		grid.add(targetModeBox);
		grid.add(header("Zeal"));
		for (int i = 0; i < SKILLS.length; i++)
		{
			final int idx = i;
			grid.add(muted(skillLabel(SKILLS[i])));
			from[i] = field(idx);
			grid.add(from[i]);
			target[i] = field(idx);
			grid.add(target[i]);
			zealNeeded[i] = value();
			grid.add(zealNeeded[i]);
		}
		return grid;
	}

	private JTextField field(int idx)
	{
		final JTextField f = new JTextField(4);
		f.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override
			public void insertUpdate(DocumentEvent e)
			{
				recompute(idx);
			}

			@Override
			public void removeUpdate(DocumentEvent e)
			{
				recompute(idx);
			}

			@Override
			public void changedUpdate(DocumentEvent e)
			{
				recompute(idx);
			}
		});
		return f;
	}

	private JPanel buildReference()
	{
		final List<Integer> levels = bandLevels();
		final JPanel grid = new JPanel(new GridLayout(levels.size() + 1, 4, 5, 2));
		grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
		grid.add(centered("Lvl", ColorScheme.LIGHT_GRAY_COLOR));
		grid.add(centered("Mel/HP", ColorScheme.LIGHT_GRAY_COLOR));
		grid.add(centered("Rng/Mag", ColorScheme.LIGHT_GRAY_COLOR));
		grid.add(centered("Pray", ColorScheme.LIGHT_GRAY_COLOR));
		for (int lvl : levels)
		{
			grid.add(centered(Integer.toString(lvl), ColorScheme.LIGHT_GRAY_COLOR));
			grid.add(centered(Integer.toString(SoulWarsXpCalculator.xpPerToken(Skill.ATTACK, lvl)), Color.WHITE));
			grid.add(centered(Integer.toString(SoulWarsXpCalculator.xpPerToken(Skill.RANGED, lvl)), Color.WHITE));
			grid.add(centered(Integer.toString(SoulWarsXpCalculator.xpPerToken(Skill.PRAYER, lvl)), Color.WHITE));
		}
		return grid;
	}

	/** Levels where XP-per-token steps up (a new band), from 30 to 99. */
	private static List<Integer> bandLevels()
	{
		final List<Integer> levels = new ArrayList<>();
		int lastMult = -1;
		for (int lvl = SoulWarsXpCalculator.MIN_LEVEL; lvl <= 99; lvl++)
		{
			final int mult = lvl * lvl / 600;
			if (mult != lastMult)
			{
				levels.add(lvl);
				lastMult = mult;
			}
		}
		if (!levels.contains(99))
		{
			levels.add(99);
		}
		return levels;
	}

	/** EDT only. -1 for tokens/lifetime/dailyXp means "unknown". */
	void update(int tokens, int lifetime, int dailyXp, int[] levels, int[] xps)
	{
		tokensValue.setText(tokens >= 0 ? format(tokens) : "open Nomad");
		lifetimeValue.setText(lifetime >= 0 ? format(lifetime) : "—");
		cratesValue.setText(tokens >= 0 ? Integer.toString(SoulWarsXpCalculator.cratesAffordable(tokens)) : "—");
		dailyValue.setText(dailyXp >= 0 ? format(dailyXp) + " / 1M" : "—");
		resetsValue.setText(timeToReset());

		boolean known = false;
		for (int i = 0; i < SKILLS.length; i++)
		{
			currentLvl[i] = levels != null && i < levels.length ? levels[i] : -1;
			currentXp[i] = xps != null && i < xps.length ? xps[i] : 0;
			known |= currentLvl[i] >= 1;
		}
		// fill From/Target from the character once, then leave both entirely to the user
		if (!seeded && known)
		{
			seeded = true;
			for (int i = 0; i < SKILLS.length; i++)
			{
				seedFrom(i);
				seedTarget(i);
			}
		}
		for (int i = 0; i < SKILLS.length; i++)
		{
			recompute(i);
		}
	}

	private void onFromModeChanged()
	{
		fromXpMode = fromModeBox.getSelectedIndex() == 1;
		for (int i = 0; i < SKILLS.length; i++)
		{
			seedFrom(i);
			recompute(i);
		}
	}

	private void onTargetModeChanged()
	{
		targetXpMode = targetModeBox.getSelectedIndex() == 1;
		for (int i = 0; i < SKILLS.length; i++)
		{
			seedTarget(i);
			recompute(i);
		}
	}

	private void seedFrom(int i)
	{
		from[i].setText(seedText(i, fromXpMode));
	}

	private void seedTarget(int i)
	{
		target[i].setText(seedText(i, targetXpMode));
	}

	private String seedText(int i, boolean xpMode)
	{
		return xpMode
			? Integer.toString(Math.max(currentXp[i], 0))
			: Integer.toString(Math.max(currentLvl[i], 1));
	}

	private void recompute(int i)
	{
		final long fromXp = fieldToXp(from[i].getText(), fromXpMode);
		final long targetXp = fieldToXp(target[i].getText(), targetXpMode);
		if (fromXp < 0 || targetXp < 0)
		{
			zealNeeded[i].setText("—");
			return;
		}
		final long tokens = SoulWarsXpCalculator.tokensToXp(
			SKILLS[i], (int) Math.min(fromXp, SoulWarsXpCalculator.MAX_XP), targetXp);
		zealNeeded[i].setText(tokens <= 0 ? "—" : format((int) Math.min(tokens, Integer.MAX_VALUE)));
	}

	/** Interpret a From/Target field as total XP, as a level or as raw XP per that column's mode. */
	private static long fieldToXp(String text, boolean xpMode)
	{
		if (xpMode)
		{
			return SoulWarsXpCalculator.parseXp(text);
		}
		final int lvl = parseInt(text);
		if (lvl < 1 || lvl > Experience.MAX_REAL_LEVEL)
		{
			return -1;
		}
		return Experience.getXpForLevel(lvl);
	}

	private static String timeToReset()
	{
		final long ms = MS_PER_DAY - (System.currentTimeMillis() % MS_PER_DAY);
		return (ms / 3_600_000L) + "h " + ((ms % 3_600_000L) / 60_000L) + "m";
	}

	private static int parseInt(String s)
	{
		if (s == null)
		{
			return -1;
		}
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static String format(int n)
	{
		return String.format("%,d", n);
	}

	private static String skillLabel(Skill skill)
	{
		final String s = skill.getName();
		return s.length() > 4 ? s.substring(0, 4) : s;
	}

	private JLabel title(String text)
	{
		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeBoldFont());
		l.setForeground(Color.WHITE);
		l.setBorder(BorderFactory.createEmptyBorder(2, 0, 4, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private JLabel blurb()
	{
		final JLabel l = new JLabel("<html>XP entry accepts 1000K, 1M, 1.12M, 200M or 200000000 "
			+ "(commas optional).</html>");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private static JLabel header(String text)
	{
		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return l;
	}

	private static JLabel muted(String text)
	{
		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return l;
	}

	private static JLabel centered(String text, Color color)
	{
		final JLabel l = new JLabel(text, SwingConstants.CENTER);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(color);
		return l;
	}

	private static JLabel value()
	{
		final JLabel l = new JLabel("—");
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(Color.WHITE);
		return l;
	}

	private JPanel gap()
	{
		final JPanel p = new JPanel();
		p.setBackground(ColorScheme.DARK_GRAY_COLOR);
		p.setPreferredSize(new Dimension(1, 8));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
		return p;
	}
}

package com.anonyser.followplus;

import java.awt.Color;

/**
 * The two Soul Wars teams, keyed off the {@code SOUL_WARS_TEAM} varbit (verified live: 1 = blue,
 * 2 = red; 0 = not in a game). {@code chatIdentifier} is the lowercase phrase the capture chat
 * messages use ("the red team has captured ...").
 */
enum SoulWarsTeam
{
	NONE(0, "", "", null),
	BLUE(1, "Blue team", "blue team", new Color(80, 140, 255)),
	RED(2, "Red team", "red team", new Color(216, 60, 62));

	private final int varbit;
	private final String label;
	private final String chatIdentifier;
	private final Color color;

	SoulWarsTeam(int varbit, String label, String chatIdentifier, Color color)
	{
		this.varbit = varbit;
		this.label = label;
		this.chatIdentifier = chatIdentifier;
		this.color = color;
	}

	String label()
	{
		return label;
	}

	String chatIdentifier()
	{
		return chatIdentifier;
	}

	Color color()
	{
		return color;
	}

	static SoulWarsTeam fromVarbit(int value)
	{
		for (SoulWarsTeam team : values())
		{
			if (team.varbit == value)
			{
				return team;
			}
		}
		return NONE;
	}
}

package com.anonyser.followplus;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class SoulWarsTimeParser
{
	private static final Pattern TAG = Pattern.compile("<[^>]*>");
	private static final Pattern TIME = Pattern.compile("(?:(\\d{1,2}):)?(\\d{1,2}):(\\d{2})");

	private SoulWarsTimeParser()
	{
	}

	/**
	 * Extracts an h:mm:ss or mm:ss time from widget text (color tags and labels are fine,
	 * e.g. "&lt;col=ffffff&gt;Time Remaining: 5:03&lt;/col&gt;").
	 *
	 * @return the time in seconds, or -1 when the text contains no valid time
	 */
	static int parseTimeSeconds(String text)
	{
		if (text == null || text.isEmpty())
		{
			return -1;
		}
		final Matcher m = TIME.matcher(TAG.matcher(text).replaceAll(" "));
		if (!m.find())
		{
			return -1;
		}
		final int hours = m.group(1) != null ? Integer.parseInt(m.group(1)) : 0;
		final int minutes = Integer.parseInt(m.group(2));
		final int seconds = Integer.parseInt(m.group(3));
		if (seconds > 59 || (m.group(1) != null && minutes > 59))
		{
			return -1;
		}
		return hours * 3600 + minutes * 60 + seconds;
	}
}

package com.anonyser.followplus;

import net.runelite.api.Experience;
import net.runelite.api.Skill;

/**
 * Soul Wars reward-shop maths (no game state needed, so fully unit-tested).
 *
 * <p>Experience per Zeal Token scales with the skill's level in bands:
 * {@code xp = floor(level^2 / 600) * N}, where N is 30 (Attack/Strength/Defence/Hitpoints),
 * 27 (Magic/Ranged) or 14 (Prayer). You must be at least level 30 in a skill to spend Zeal on it,
 * and no more than 1,000,000 experience can be bought with Zeal per day. A Spoils of War crate
 * costs 30 Zeal Tokens. (All figures from the OSRS Wiki, verified against its worked examples:
 * level 99 melee = 480 xp/token, ranged = 432, prayer = 224.)
 */
final class SoulWarsXpCalculator
{
	static final int MIN_LEVEL = 30;
	static final int CRATE_COST = 30;
	static final int DAILY_XP_CAP = 1_000_000;
	static final long MAX_XP = 200_000_000L;

	private SoulWarsXpCalculator()
	{
	}

	/** The N factor for a skill, or 0 if Zeal cannot be spent on it. */
	static int multiplier(Skill skill)
	{
		switch (skill)
		{
			case PRAYER:
				return 14;
			case MAGIC:
			case RANGED:
				return 27;
			case ATTACK:
			case STRENGTH:
			case DEFENCE:
			case HITPOINTS:
				return 30;
			default:
				return 0;
		}
	}

	static boolean isTrainable(Skill skill)
	{
		return multiplier(skill) > 0;
	}

	/** Experience awarded per Zeal Token at the given level for the given skill. */
	static int xpPerToken(Skill skill, int level)
	{
		return (level * level / 600) * multiplier(skill);
	}

	/**
	 * Zeal Tokens needed to reach {@code targetLevel} from the current experience, summed level by
	 * level at each level's rate. Returns 0 if already at/above the target, and -1 if the skill
	 * cannot be trained with Zeal. Levels below {@link #MIN_LEVEL} can't be bought with Zeal, so
	 * the count starts from level 30.
	 */
	static long tokensToLevel(Skill skill, int currentXp, int targetLevel)
	{
		final int n = multiplier(skill);
		if (n == 0)
		{
			return -1;
		}
		targetLevel = Math.min(Math.max(targetLevel, 1), Experience.MAX_REAL_LEVEL);
		final int startLevel = Math.max(Experience.getLevelForXp(currentXp), MIN_LEVEL);
		if (targetLevel <= startLevel)
		{
			return 0;
		}
		long pos = Math.max(currentXp, Experience.getXpForLevel(MIN_LEVEL));
		long tokens = 0;
		for (int level = startLevel; level < targetLevel; level++)
		{
			final long boundary = Experience.getXpForLevel(level + 1);
			final long need = boundary - pos;
			if (need > 0)
			{
				final int rate = xpPerToken(skill, level); // level >= 30, so rate >= 30
				tokens += (need + rate - 1) / rate; // ceil
			}
			pos = boundary;
		}
		return tokens;
	}

	/**
	 * Zeal Tokens needed to reach a target total experience from the current experience, summed at
	 * each level's rate (levels past 99 keep the level-99 rate). Returns 0 if already there, -1 if
	 * the skill can't be trained with Zeal.
	 */
	static long tokensToXp(Skill skill, int currentXp, long targetXp)
	{
		final int n = multiplier(skill);
		if (n == 0)
		{
			return -1;
		}
		targetXp = Math.min(Math.max(targetXp, 0), MAX_XP);
		long pos = Math.max(currentXp, Experience.getXpForLevel(MIN_LEVEL));
		if (targetXp <= pos)
		{
			return 0;
		}
		long tokens = 0;
		int level = Math.max(Experience.getLevelForXp((int) pos), MIN_LEVEL);
		while (pos < targetXp)
		{
			final long boundary = level < Experience.MAX_REAL_LEVEL
				? Math.min(targetXp, Experience.getXpForLevel(level + 1)) : targetXp;
			final long need = boundary - pos;
			if (need > 0)
			{
				final int rate = xpPerToken(skill, Math.min(level, Experience.MAX_REAL_LEVEL));
				tokens += (need + rate - 1) / rate; // ceil
			}
			pos = boundary;
			level++;
		}
		return tokens;
	}

	/**
	 * Parses a player-friendly experience value: a plain number (commas/spaces optional) or a
	 * shorthand with a K/M/B suffix, e.g. "200000000", "200,000,000", "200M", "1.12M", "1000K".
	 * Returns -1 if it can't be parsed.
	 */
	static long parseXp(String text)
	{
		if (text == null)
		{
			return -1;
		}
		String s = text.trim().toUpperCase().replace(",", "").replace(" ", "");
		if (s.isEmpty())
		{
			return -1;
		}
		double mult = 1;
		final char last = s.charAt(s.length() - 1);
		if (last == 'K')
		{
			mult = 1_000;
		}
		else if (last == 'M')
		{
			mult = 1_000_000;
		}
		else if (last == 'B')
		{
			mult = 1_000_000_000;
		}
		if (mult != 1)
		{
			s = s.substring(0, s.length() - 1);
		}
		try
		{
			final double v = Double.parseDouble(s) * mult;
			return v < 0 ? -1 : (long) v;
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	/** How many Spoils of War crates the given Zeal Token balance can buy. */
	static int cratesAffordable(int zealTokens)
	{
		return Math.max(0, zealTokens) / CRATE_COST;
	}
}

package com.anonyser.followplus;

import java.awt.Color;

/**
 * One line of the status display, shared by the in-game overlay and the external window so the
 * line-building logic lives in exactly one place (the plugin). A {@code header} renders bold /
 * banner-style; otherwise {@code left} is the label and {@code right} the value. {@code color}
 * tints the value (overlay) or the whole line (window); null means the default colour. When
 * {@code flash} is set the line pulses through {@link #flashColor} to demand attention (low
 * activity, low prayer, game nearly over).
 */
final class StatusLine
{
	private static final Color[] FLASH = {
		new Color(255, 80, 80), new Color(255, 215, 60), new Color(255, 255, 255)
	};

	final String left;
	final String right;
	final Color color;
	final boolean header;
	final boolean flash;

	private StatusLine(String left, String right, Color color, boolean header, boolean flash)
	{
		this.left = left;
		this.right = right;
		this.color = color;
		this.header = header;
		this.flash = flash;
	}

	static StatusLine header(String text, Color color)
	{
		return new StatusLine(text, null, color, true, false);
	}

	/** Label + value line. */
	static StatusLine of(String left, String right, Color color)
	{
		return new StatusLine(left, right, color, false, false);
	}

	/** Single-text line (no value column), e.g. a status such as "Not following anyone". */
	static StatusLine plain(String text, Color color)
	{
		return new StatusLine(text, null, color, false, false);
	}

	/** A label + value line that flashes for attention. */
	static StatusLine alert(String left, String right, Color color)
	{
		return new StatusLine(left, right, color, false, true);
	}

	/** The current flash colour for the given time, cycling through several attention colours. */
	static Color flashColor(long millis)
	{
		return FLASH[(int) ((millis / 300) % FLASH.length)];
	}
}

package com.anonyser.followplus;

final class TimeFormat
{
	private TimeFormat()
	{
	}

	/** Formats seconds as m:ss, or h:mm:ss above an hour. Negative values clamp to 0:00. */
	static String mmss(double seconds)
	{
		final long total = (long) Math.max(0, seconds);
		final long h = total / 3600;
		final long m = (total % 3600) / 60;
		final long s = total % 60;
		return h > 0
			? String.format("%d:%02d:%02d", h, m, s)
			: String.format("%d:%02d", m, s);
	}
}

package com.anonyser.followplus;

/**
 * Tracks Soul Wars Zeal from the two account varps (verified live):
 * <ul>
 *   <li>lifetime Zeal — the cumulative score, varp 2871 (only ever rises),</li>
 *   <li>Zeal Token balance — the spendable currency, varp 2876.</li>
 * </ul>
 *
 * <p>Both are handed in on each update; everything else is derived from the lifetime value's
 * movement, so this class holds no game references and is fully unit-tested. "Zeal earned" for a
 * game / session / since install is just the rise in lifetime Zeal between two anchors. The
 * install anchor is persisted by the plugin (in config); the session and last-game anchors live
 * for the session only.
 *
 * <p>A varp reading of -1 means "not known yet" (e.g. before the game has synced it) and is
 * ignored, so a missing value never corrupts an anchor.
 */
class ZealTracker
{
	private int lifetime = -1;
	private int tokens = -1;

	private long sessionStartMs;
	private int sessionStartLifetime = -1;

	private boolean inGamePrev;
	private int gameStartLifetime = -1;
	private int lastGameGained = -1;

	void startSession(long nowMs)
	{
		sessionStartMs = nowMs;
		sessionStartLifetime = -1;
		inGamePrev = false;
		gameStartLifetime = -1;
		lastGameGained = -1;
	}

	/**
	 * Feed the latest readings. {@code lifetimeZeal} / {@code tokenBalance} are the raw varp values
	 * (-1 if not yet known); {@code inGame} is true while in a Soul Wars game.
	 */
	void update(int lifetimeZeal, int tokenBalance, boolean inGame, long nowMs)
	{
		if (lifetimeZeal >= 0)
		{
			lifetime = lifetimeZeal;
			if (sessionStartLifetime < 0)
			{
				sessionStartLifetime = lifetimeZeal;
			}
		}
		if (tokenBalance >= 0)
		{
			tokens = tokenBalance;
		}

		// Game boundaries drive "last game" zeal: anchor lifetime on entry, diff it on exit.
		if (inGame && !inGamePrev && lifetime >= 0)
		{
			gameStartLifetime = lifetime;
		}
		else if (!inGame && inGamePrev && gameStartLifetime >= 0 && lifetime >= gameStartLifetime)
		{
			lastGameGained = lifetime - gameStartLifetime;
		}
		inGamePrev = inGame;
	}

	boolean lifetimeKnown()
	{
		return lifetime >= 0;
	}

	int lifetime()
	{
		return lifetime;
	}

	int tokens()
	{
		return tokens;
	}

	/** Zeal gained since the plugin started this session, or -1 until lifetime is known. */
	int sessionGained()
	{
		return lifetime >= 0 && sessionStartLifetime >= 0 ? lifetime - sessionStartLifetime : -1;
	}

	/** Zeal earned in the most recent completed game this session, or -1 if none yet. */
	int lastGameGained()
	{
		return lastGameGained;
	}

	long sessionMillis(long nowMs)
	{
		return Math.max(0, nowMs - sessionStartMs);
	}

	/** Estimated Zeal per hour this session (session gain over session time), or -1 if not ready. */
	int zealPerHour(long nowMs)
	{
		final long ms = sessionMillis(nowMs);
		final int gained = sessionGained();
		if (gained <= 0 || ms < 1000)
		{
			return -1;
		}
		return (int) (gained * 3_600_000L / ms);
	}
}

package com.anonyser.followplus;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ActivityDecayEstimatorTest
{
	private static final double EPS = 0.0001;

	@Test
	public void unknownUntilADecayIsObserved()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		assertEquals(-1, e.ticksToZero(0), EPS);
		e.onValue(800, 0);
		assertEquals(-1, e.ticksToZero(5), EPS);
	}

	@Test
	public void estimatesFromObservedDecay()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		e.onValue(800, 0);
		e.onValue(760, 5); // -40 over 5 ticks = 8/tick
		assertEquals(95.0, e.ticksToZero(5), EPS); // 760 / 8
		// between changes the estimate keeps counting down
		assertEquals(90.0, e.ticksToZero(10), EPS);
	}

	@Test
	public void activityGainJustMovesTheBaseline()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		e.onValue(400, 0);
		e.onValue(360, 5); // 8/tick
		e.onValue(800, 6); // player did something
		assertEquals(100.0, e.ticksToZero(6), EPS); // 800 / 8
	}

	@Test
	public void estimateNeverGoesNegative()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		e.onValue(80, 0);
		e.onValue(40, 5);
		assertEquals(0.0, e.ticksToZero(1000), EPS);
	}

	@Test
	public void resetForgetsEverything()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		e.onValue(800, 0);
		e.onValue(760, 5);
		e.reset();
		assertEquals(-1, e.ticksToZero(10), EPS);
	}

	@Test
	public void smoothsAcrossSamples()
	{
		final ActivityDecayEstimator e = new ActivityDecayEstimator();
		e.onValue(800, 0);
		e.onValue(760, 5);  // 8/tick
		e.onValue(700, 10); // 12/tick -> smoothed 10/tick
		final double ticks = e.ticksToZero(10);
		assertTrue("expected 700/10 = 70, got " + ticks, Math.abs(ticks - 70.0) < EPS);
	}
}

package com.anonyser.followplus;

import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Skill;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class DailyXpTrackerTest
{
	private static final Set<Skill> TRACKED = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.PRAYER);
	private static final long DAY1 = 20_000L * 86_400_000L;
	private static final long DAY2 = 20_001L * 86_400_000L;

	@Test
	public void firstReadingIsBaselineOnly()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.onXp(Skill.ATTACK, 5000, true, DAY1);
		assertEquals(0, t.usedToday(DAY1));
	}

	@Test
	public void countsGainsInTrackedSkills()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.onXp(Skill.ATTACK, 5000, true, DAY1);
		t.onXp(Skill.ATTACK, 5030, true, DAY1);
		t.onXp(Skill.STRENGTH, 100, true, DAY1);
		t.onXp(Skill.STRENGTH, 160, true, DAY1);
		assertEquals(90, t.usedToday(DAY1));
	}

	@Test
	public void onlyCountsWhenFlagged()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.onXp(Skill.ATTACK, 5000, false, DAY1); // baseline
		t.onXp(Skill.ATTACK, 5100, false, DAY1); // combat: baseline moves, not counted
		assertEquals(0, t.usedToday(DAY1));
		t.onXp(Skill.ATTACK, 5150, true, DAY1); // purchase from 5100 -> +50
		assertEquals(50, t.usedToday(DAY1));
	}

	@Test
	public void ignoresUntrackedSkills()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.onXp(Skill.WOODCUTTING, 100, true, DAY1);
		t.onXp(Skill.WOODCUTTING, 999, true, DAY1);
		assertEquals(0, t.usedToday(DAY1));
	}

	@Test
	public void rollsOverAtDayBoundary()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.onXp(Skill.ATTACK, 5000, true, DAY1);
		t.onXp(Skill.ATTACK, 5100, true, DAY1);
		assertEquals(100, t.usedToday(DAY1));
		assertEquals(0, t.usedToday(DAY2));
		t.onXp(Skill.ATTACK, 5100, true, DAY2);
		t.onXp(Skill.ATTACK, 5150, true, DAY2);
		assertEquals(50, t.usedToday(DAY2));
	}

	@Test
	public void seedRestoresTotal()
	{
		final DailyXpTracker t = new DailyXpTracker(TRACKED);
		t.seed(20_000L, 12345);
		assertEquals(12345, t.usedToday(DAY1));
		assertEquals(20_000L, t.dayKey());
		// a purchase adds onto the restored total
		t.onXp(Skill.ATTACK, 1000, false, DAY1);
		t.onXp(Skill.ATTACK, 1050, true, DAY1);
		assertEquals(12395, t.usedToday(DAY1));
	}
}

